from datetime import datetime, timedelta
from functools import partial
from funcy import cache, reraise, SkipMemoization

calls = []
@cache(60, key_func=lambda x: x)
def cached(x):
    calls.append(x)
    return x * 2
assert cached.memory == {}
assert cached.skip is SkipMemoization
assert cached(2) == cached(2) == 4
assert calls == [2]
assert cached.memory[2][0] == 4
cached.memory[2] = (9, datetime.now())
assert cached(2) == 9
cached.memory[2] = (9, datetime.now() - timedelta(seconds=61))
assert cached(2) == 4
memory = cached.memory
cached.invalidate(2)
assert memory == {}
cached(3)
cached.invalidate_all()
assert cached.memory is memory and memory == {}

original = ValueError('bad')
seen = []
def transform(e):
    seen.append(e)
    return RuntimeError('converted: ' + str(e))
for as_decorator in (False, True):
    try:
        if as_decorator:
            @reraise(ValueError, transform)
            def fail():
                raise original
            fail()
        else:
            with reraise(ValueError, transform):
                raise original
    except RuntimeError as e:
        assert str(e) == 'converted: bad' and e.__cause__ is original
    else:
        assert False
assert seen == [original, original]
for target in (RuntimeError, RuntimeError('fixed'), partial(RuntimeError, 'prefix')):
    try:
        with reraise(ValueError, target):
            raise original
    except RuntimeError as e:
        assert e.__cause__ is original
        if target is RuntimeError:
            assert e.args == ()
        elif isinstance(target, BaseException):
            assert e is target
        else:
            assert e.args == ('prefix', original)
with reraise(ValueError, transform):
    pass
try:
    with reraise(ValueError, transform):
        raise KeyError('unmatched')
except KeyError:
    pass
else:
    assert False
assert seen == [original, original]
print('Focused cache API and reraise checks passed')
